import importlib.metadata as m, sys
def version(name):
    try:
        return m.version(name)
    except m.PackageNotFoundError:
        return None
print(repr({'python': sys.version, 'executable': sys.executable, 'flask': version('flask'), 'werkzeug': version('werkzeug'),
            'extensions': {n: version(n) for n in ('flask-restx', 'flask-restful', 'flask-admin', 'flask-smorest', 'apifairy', 'flask-appbuilder', 'flask-dotenv', 'python-dotenv')
                           if version(n)}, 'packages': len(list(m.distributions()))}))
